import { test, expect } from '@playwright/test';

test.describe('Username Availability Validation', () => {
  let page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('data:text/html,<html><body><form><input id="username" placeholder="Enter username" /><button id="check-btn">Check Availability</button><div id="result"></div></form><script>document.getElementById("check-btn").addEventListener("click", async () => { const username = document.getElementById("username").value; const response = await fetch(`/api/check-username?username=${username}`); const data = await response.json(); document.getElementById("result").textContent = data.available ? "Username available" : "Username taken"; });</script></body></html>');
  });

  test('should validate username availability asynchronously', async () => {
    const usernameInput = page.getByRole('textbox');
    const checkButton = page.getByRole('button', { name: 'Check Availability' });

    await usernameInput.fill('newuser123');

    // Mock the API response
    await page.route('**/api/check-username**', route => {
      route.abort();
    });

    await checkButton.click();

    // Verify the input was filled
    await expect(usernameInput).toHaveValue('newuser123');
  });

  test('should handle username availability check with valid response', async () => {
    const usernameInput = page.getByRole('textbox');
    const checkButton = page.getByRole('button', { name: 'Check Availability' });
    const resultDiv = page.locator('#result');

    // Mock successful API response
    await page.route('**/api/check-username**', route => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ available: true })
      });
    });

    await usernameInput.fill('availableuser');
    await checkButton.click();

    // Wait for async validation to complete
    await expect(resultDiv).toContainText('Username available', { timeout: 5000 });
  });

  test('should display taken message when username is unavailable', async () => {
    const usernameInput = page.getByRole('textbox');
    const checkButton = page.getByRole('button', { name: 'Check Availability' });
    const resultDiv = page.locator('#result');

    // Mock API response indicating username is taken
    await page.route('**/api/check-username**', route => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ available: false })
      });
    });

    await usernameInput.fill('takenuser');
    await checkButton.click();

    // Wait for async validation to complete
    await expect(resultDiv).toContainText('Username taken', { timeout: 5000 });
  });

  test('should handle empty username validation', async () => {
    const usernameInput = page.getByRole('textbox');
    const checkButton = page.getByRole('button', { name: 'Check Availability' });

    // Leave username empty
    await expect(usernameInput).toHaveValue('');

    // Verify button is clickable even with empty input
    await expect(checkButton).toBeEnabled();
  });
});
